const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const env = typeof $env === 'object' && $env ? $env : {};
const sourcePayload = $json.source_payload_json ?? {};
const creativeDefaults = sourcePayload.creative_defaults && typeof sourcePayload.creative_defaults === 'object'
  ? sourcePayload.creative_defaults
  : {};
const flattenText = (value, keyPath = '') => {
  if (value == null) return [];
  if (typeof value === 'string' || typeof value === 'number' || typeof value === 'boolean') {
    const text = String(value).trim();
    return text ? [keyPath + text] : [];
  }
  if (Array.isArray(value)) {
    return value.flatMap((entry, index) => flattenText(entry, keyPath ? keyPath + (index + 1) + '. ' : ''));
  }
  if (typeof value === 'object') {
    return Object.entries(value).flatMap(([key, entry]) => flattenText(entry, key + ': '));
  }
  return [];
};
const sourceNotesLines = [];
if (Array.isArray(sourcePayload.notes)) {
  sourceNotesLines.push(...sourcePayload.notes.map((entry) => String(entry ?? '').trim()).filter(Boolean));
}
for (const key of ['abstract_idea', 'summary', 'description', 'context', 'narrative_perspective', 'point_of_view', 'visual_direction', 'visual_strategy', 'source_text']) {
  const text = String(sourcePayload[key] ?? '').trim();
  if (text) sourceNotesLines.push(text);
}
if (Object.keys(creativeDefaults).length > 0) {
  sourceNotesLines.push('Creative defaults: ' + JSON.stringify(creativeDefaults));
}
if (sourceNotesLines.length === 0) {
  sourceNotesLines.push(...flattenText(sourcePayload));
}
const contentId = String($json.content_id ?? '').trim();
const title = String($json.title ?? '').trim();
if (!uuidPattern.test(contentId)) {
  throw new Error('Fetch Next Approved Item did not atomically claim a valid content_id. Run from the start and ensure an idea_approved row exists.');
}
if (!title) {
  throw new Error('Fetch Next Approved Item did not produce a title. Re-run from Manual Trigger and inspect the fetch node output.');
}
const targetDurationSeconds = Number($json.target_duration_seconds ?? 45);
if (!Number.isFinite(targetDurationSeconds) || targetDurationSeconds <= 0) {
  throw new Error('target_duration_seconds must be a positive number.');
}
const category = String($json.category ?? 'general').trim() || 'general';
const confidenceLabel = String($json.confidence_label ?? 'unverified').trim() || 'unverified';
const sourceNotes = sourceNotesLines.length ? sourceNotesLines.join('\\n') : 'No source notes were provided. Keep the script cautious and explicit about uncertainty.';
const confidenceContext = 'Current stored confidence label: ' + confidenceLabel + '. Preserve or lower certainty unless the source notes clearly support a stronger confidence label.';
const brandTone = String(env.RESEARCH_BRAND_TONE || creativeDefaults.tone || env.STUDIO_BRAND_TONE || 'cinematic, concise, credible').trim() || 'cinematic, concise, credible';
const narratorStyle = String(env.RESEARCH_NARRATOR_STYLE || creativeDefaults.narrator_style || creativeDefaults.voice_role_hint || 'calm, serious, engaging').trim() || 'calm, serious, engaging';
const endingSignatureFamily = String(env.RESEARCH_ENDING_SIGNATURE_FAMILY || 'thought-provoking close').trim() || 'thought-provoking close';
const promptPayload = {
  content_id: contentId,
  title,
  confidence_label: confidenceLabel,
  target_duration_seconds: targetDurationSeconds,
  status_after_success: 'script_complete',
  prompt_template_data: {
    target_duration_seconds: String(targetDurationSeconds),
    brand_tone: brandTone,
    narrator_style: narratorStyle,
    ending_signature_family: endingSignatureFamily,
    topic: title,
    category,
    confidence_context: confidenceContext,
    source_notes: sourceNotes,
    creative_defaults: creativeDefaults,
    creative_defaults_json: Object.keys(creativeDefaults).length > 0 ? JSON.stringify(creativeDefaults, null, 2) : '{}',
    narrative_perspective: String(creativeDefaults.narrative_perspective || sourcePayload.narrative_perspective || '').trim(),
    voice_role_hint: String(creativeDefaults.voice_role_hint || '').trim(),
    visual_strategy: String(creativeDefaults.visual_strategy || sourcePayload.visual_strategy || sourcePayload.visual_direction || '').trim(),
    music_mood: String(creativeDefaults.music_mood || '').trim(),
  },
};
return [{
  json: {
    ...promptPayload,
    prompt_payload_base64: Buffer.from(JSON.stringify(promptPayload), 'utf8').toString('base64')
  }
}];

const stdout = String($json.stdout ?? '').trim();
if (!stdout) {
  throw new Error('Research model adapter returned no stdout.');
}
let parsed;
try {
  parsed = JSON.parse(stdout);
} catch (error) {
  throw new Error('Research model adapter returned invalid JSON: ' + error.message);
}
if (!parsed.content_id || !parsed.title || !parsed.llm_response) {
  throw new Error('Research model adapter did not provide the expected structured response.');
}
return [{ json: parsed }];

const response = $json.llm_response ?? {};
if (!$json.content_id) {
  throw new Error('Research model adapter did not provide content_id to Normalize Script Package.');
}
const targetDurationSeconds = Number($json.target_duration_seconds ?? 0);
const requiredTextFields = [
  'confidence_label',
  'hook_option_1',
  'hook_option_2',
  'hook_option_3',
  'selected_hook',
  'narration_script',
  'short_script',
  'caption_draft',
  'cta_line',
  'music_direction'
];
for (const field of requiredTextFields) {
  if (!String(response[field] ?? '').trim()) {
    throw new Error('Research model adapter returned an empty ' + field + '.');
  }
}
if (!Array.isArray(response.onscreen_text_json) || response.onscreen_text_json.length === 0) {
  throw new Error('Research model adapter did not produce onscreen_text_json.');
}
const onscreenTextJson = response.onscreen_text_json.map((entry, index) => ({
  scene_number: Number(entry?.scene_number ?? index + 1),
  text: String(entry?.text ?? '').trim()
}));
if (onscreenTextJson.some((entry) => !Number.isInteger(entry.scene_number) || entry.scene_number < 1 || !entry.text)) {
  throw new Error('onscreen_text_json must contain positive scene_number values and non-empty text.');
}
if (!Array.isArray(response.scene_guidance_json) || response.scene_guidance_json.length < 4 || response.scene_guidance_json.length > 8) {
  throw new Error('Research model adapter did not produce scene_guidance_json with 4 to 8 scenes.');
}
const roundToHundredths = (value) => Number(Number(value).toFixed(2));
const sceneGuidanceJson = response.scene_guidance_json.map((scene, index) => ({
  scene_number: Number(scene?.scene_number ?? index + 1),
  beat_label: String(scene?.beat_label ?? '').trim(),
  start_time_seconds: roundToHundredths(Number(scene?.start_time_seconds ?? 0)),
  end_time_seconds: roundToHundredths(Number(scene?.end_time_seconds ?? 0)),
  duration_seconds: roundToHundredths(Number(scene?.duration_seconds ?? 0)),
  narration_text: String(scene?.narration_text ?? '').trim(),
  dialogue_lines: Array.isArray(scene?.dialogue_lines) ? scene.dialogue_lines.map((line) => String(line ?? '').trim()).filter(Boolean) : [String(scene?.narration_text ?? '').trim()].filter(Boolean),
  asset_type: ['image', 'video'].includes(String(scene?.asset_type ?? '').trim()) ? String(scene?.asset_type ?? '').trim() : 'image',
  scene_purpose: String(scene?.scene_purpose ?? '').trim(),
  visual_beat: String(scene?.visual_beat ?? '').trim(),
  source_boundary: String(scene?.source_boundary ?? '').trim(),
  music_cue: String(scene?.music_cue ?? '').trim(),
}));
let previousEndSeconds = 0;
for (const [index, scene] of sceneGuidanceJson.entries()) {
  if (scene.scene_number !== index + 1) {
    throw new Error('scene_guidance_json scene_number values must be sequential starting at 1.');
  }
  if (!scene.beat_label) {
    throw new Error('scene_guidance_json contains an empty beat_label.');
  }
  if (!Number.isFinite(scene.start_time_seconds) || !Number.isFinite(scene.end_time_seconds) || !Number.isFinite(scene.duration_seconds)) {
    throw new Error('scene_guidance_json timing fields must be numeric.');
  }
  if (scene.start_time_seconds < 0 || scene.end_time_seconds <= scene.start_time_seconds || scene.duration_seconds <= 0) {
    throw new Error('scene_guidance_json contains invalid timing ranges.');
  }
  const derivedDurationSeconds = roundToHundredths(scene.end_time_seconds - scene.start_time_seconds);
  if (Math.abs(derivedDurationSeconds - scene.duration_seconds) > 0.75) {
    throw new Error('scene_guidance_json duration_seconds must match end_time_seconds - start_time_seconds.');
  }
  if (!scene.narration_text) {
    throw new Error('scene_guidance_json contains an empty narration_text.');
  }
  if (!scene.dialogue_lines.length) {
    throw new Error('scene_guidance_json contains empty dialogue_lines.');
  }
  if (!['image', 'video'].includes(scene.asset_type)) {
    throw new Error('scene_guidance_json contains an invalid asset_type.');
  }
  if (!scene.scene_purpose) {
    throw new Error('scene_guidance_json contains an empty scene_purpose.');
  }
  if (!scene.visual_beat) {
    throw new Error('scene_guidance_json contains an empty visual_beat.');
  }
  if (!scene.source_boundary) {
    throw new Error('scene_guidance_json contains an empty source_boundary.');
  }
  if (!scene.music_cue) {
    throw new Error('scene_guidance_json contains an empty music_cue.');
  }
  if (index === 0 && Math.abs(scene.start_time_seconds) > 0.5) {
    throw new Error('scene_guidance_json must start at 0 seconds.');
  }
  if (index > 0 && Math.abs(scene.start_time_seconds - previousEndSeconds) > 0.75) {
    throw new Error('scene_guidance_json timings must be contiguous from one scene to the next.');
  }
  previousEndSeconds = scene.end_time_seconds;
}
if (Number.isFinite(targetDurationSeconds) && targetDurationSeconds > 0) {
  const finalEndSeconds = sceneGuidanceJson[sceneGuidanceJson.length - 1]?.end_time_seconds ?? 0;
  if (Math.abs(finalEndSeconds - targetDurationSeconds) > Math.max(2, targetDurationSeconds * 0.2)) {
    throw new Error('scene_guidance_json must end close to the target_duration_seconds.');
  }
}
return [{
  json: {
    content_id: $json.content_id,
    title: $json.title,
    status_after_success: $json.status_after_success,
    target_duration_seconds: targetDurationSeconds,
    confidence_label: String(response.confidence_label).trim(),
    hook_option_1: String(response.hook_option_1).trim(),
    hook_option_2: String(response.hook_option_2).trim(),
    hook_option_3: String(response.hook_option_3).trim(),
    selected_hook: String(response.selected_hook).trim(),
    narration_script: String(response.narration_script).trim(),
    short_script: String(response.short_script).trim(),
    caption_draft: String(response.caption_draft).trim(),
    cta_line: String(response.cta_line).trim(),
    music_direction: String(response.music_direction).trim(),
    onscreen_text_json: onscreenTextJson,
    scene_guidance_json: sceneGuidanceJson,
    generation_model: String($json.generation_model ?? '').trim(),
    cost: $json.cost ?? {},
    raw_response_json: {
      provider: String($json.generation_provider ?? $json.llm_provider ?? 'openai').trim(),
      generation_model: String($json.generation_model ?? '').trim(),
      provider_metadata: $json.provider_metadata ?? {},
      scene_guidance_json: sceneGuidanceJson,
      parsed_response: {
        ...response,
        scene_guidance_json: sceneGuidanceJson
      }
    }
  }
}];

const cost_json_sql = JSON.stringify($json.cost ?? {}).replaceAll("'", "''");
const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const contentId = String($json.content_id ?? '').trim();
if (!uuidPattern.test(contentId)) {
  throw new Error('Prepare SQL Values received an invalid content_id: ' + (contentId || '<empty>') + '. Re-run from Manual Trigger and verify earlier nodes are not pinned or stale.');
}
return [{
  json: {
    ...$json,
    content_id_sql: contentId,
